        body {
            font-family: Georgia, "Times New Roman", serif;
            color: var(--ink);
            background:
                radial-gradient(circle at top, rgba(183, 138, 66, 0.16), transparent 34%),
                linear-gradient(180deg, #f5e7d6 0%, var(--paper) 42%, #fbf7f1 100%);
            line-height: 1.72;
        }

        a { color: inherit; text-decoration: none; }

        .container {
            width: min(1120px, calc(100% - 40px));
            margin: 0 auto;
        }

        .topbar {
            position: sticky;
            top: 0;
            z-index: 10;
            backdrop-filter: blur(14px);
            background: rgba(248, 241, 231, 0.88);
            border-bottom: 1px solid rgba(36, 25, 21, 0.08);
        }

        .topbar-inner {
            min-height: 74px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 18px;
        }

        .brand {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .brand-mark {
            font-size: 13px;
            letter-spacing: 0.18em;
            text-transform: uppercase;
            color: var(--cinnabar);
        }

        .brand-name {
            font-size: 24px;
            font-weight: 700;
        }

        .nav {
            display: flex;
            gap: 18px;
            font-size: 14px;
            color: rgba(36, 25, 21, 0.78);
            flex-wrap: wrap;
            justify-content: flex-end;
        }

        .hero {
            padding: 74px 0 56px;
        }

        .hero-grid {
            display: grid;
            grid-template-columns: minmax(0, 1.12fr) minmax(320px, 0.88fr);
            gap: 30px;
            align-items: stretch;
        }

