        .hero-panel,
        .story-card,
        .plan-card,
        .carrier-card,
        .step,
        .faq-item,
        .closing-card {
            background: rgba(255, 253, 248, 0.9);
            border: 1px solid rgba(36, 25, 21, 0.08);
            box-shadow: var(--shadow);
        }

        .hero-copy {
            padding: 44px;
            border-radius: 28px;
        }

        .eyebrow {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            font-size: 12px;
            letter-spacing: 0.18em;
            text-transform: uppercase;
            color: var(--gold);
            margin-bottom: 18px;
